def seed(apps, schema_editor):
    Organization = apps.get_model("core", "Organization")
    ClubMeeting = apps.get_model("core", "ClubMeeting")
    for club, day, time, freq, room, note in SEED:
        org = Organization.objects.filter(name__iexact=club).first()
        if org:
            ClubMeeting.objects.create(
                organization=org, day=day, time=time, freq=freq, room=room, note=note
            )


def grant_perms(apps, schema_editor):
    # owners/execs edit meetings inline, so their groups need rights on the new model
    ContentType = apps.get_model("contenttypes", "ContentType")
    Group = apps.get_model("auth", "Group")
    Permission = apps.get_model("auth", "Permission")
    ct, _ = ContentType.objects.get_or_create(app_label="core", model="clubmeeting")
    perms = [
        Permission.objects.get_or_create(
            content_type=ct,
            codename=f"{a}_clubmeeting",
            defaults={"name": f"Can {a} club meeting"},
        )[0]
        for a in ("add", "change", "delete", "view")
    ]
    for name in ("Org Owners", "Execs"):
        Group.objects.get_or_create(name=name)[0].permissions.add(*perms)


